create or replace function catalog._product_custom_field_list_values_json(
  p_tenant_id uuid,
  p_product_id uuid
)
returns jsonb
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'field_id', f.id,
        'group_id', g.id,
        'group_name', g.name,
        'field_name', f.name,
        'field_type', f.field_type,
        'display_value', catalog._product_custom_field_display_value(
          f.field_type,
          v.value_text,
          v.value_number,
          v.value_date,
          v.value_boolean,
          o.label
        ),
        'sort_order', g.sort_order * 1000 + f.sort_order
      )
      order by g.sort_order, f.sort_order, f.name
    ),
    '[]'::jsonb
  )
  from catalog.custom_field_groups g
  join catalog.custom_fields f
    on f.group_id = g.id
   and f.tenant_id = p_tenant_id
  join catalog.product_custom_field_values v
    on v.custom_field_id = f.id
   and v.product_id = p_product_id
   and v.tenant_id = p_tenant_id
  left join catalog.custom_field_options o
    on o.id = v.value_option_id
  where g.tenant_id = p_tenant_id
    and g.status = 'active'
    and f.status = 'active'
    and f.display_on_list = true
    and nullif(
      btrim(
        coalesce(
          catalog._product_custom_field_display_value(
            f.field_type,
            v.value_text,
            v.value_number,
            v.value_date,
            v.value_boolean,
            o.label
          ),
          ''
        )
      ),
      ''
    ) is not null;
$$;

create or replace function catalog._product_matches_custom_field_keyword(
  p_tenant_id uuid,
  p_product_id uuid,
  p_keyword text
)
returns boolean
language sql
stable
security definer
set search_path = catalog, pg_temp
as $$
  select exists (
    select 1
    from catalog.custom_field_groups g
    join catalog.custom_fields f
      on f.group_id = g.id
     and f.tenant_id = p_tenant_id
    join catalog.product_custom_field_values v
      on v.custom_field_id = f.id
     and v.product_id = p_product_id
     and v.tenant_id = p_tenant_id
    left join catalog.custom_field_options o
      on o.id = v.value_option_id
    where g.tenant_id = p_tenant_id
      and g.status = 'active'
      and f.status = 'active'
      and f.is_searchable = true
      and f.field_type in ('text', 'singleSelect')
      and catalog._product_custom_field_display_value(
        f.field_type,
        v.value_text,
        v.value_number,
        v.value_date,
        v.value_boolean,
        o.label
      ) ilike '%' || p_keyword || '%'
  );
$$;

create or replace function catalog._product_matches_custom_field_filters(
  p_tenant_id uuid,
  p_product_id uuid,
  p_filters jsonb
)
returns boolean
language plpgsql
stable
security definer
set search_path = catalog, pg_temp
as $$
declare
  v_filter jsonb;
  v_field catalog.custom_fields%rowtype;
  v_value catalog.product_custom_field_values%rowtype;
begin
  if p_filters is null or jsonb_typeof(p_filters) <> 'array' or jsonb_array_length(p_filters) = 0 then
    return true;
  end if;

  for v_filter in select value from jsonb_array_elements(p_filters)
  loop
    select *
    into v_field
    from catalog.custom_fields f
    where f.id = (v_filter ->> 'field_id')::uuid
      and f.tenant_id = p_tenant_id;

    if not found
      or v_field.status <> 'active'
      or not v_field.is_filterable then
      return false;
    end if;

    select *
    into v_value
    from catalog.product_custom_field_values v
    where v.tenant_id = p_tenant_id
      and v.product_id = p_product_id
      and v.custom_field_id = v_field.id;

    if not found then
      return false;
    end if;

    if v_filter ? 'option_id' then
      if v_field.field_type <> 'singleSelect'
        or v_value.value_option_id is distinct from (v_filter ->> 'option_id')::uuid then
        return false;
      end if;
    elsif v_filter ? 'boolean_value' then
      if v_field.field_type <> 'boolean'
        or v_value.value_boolean is distinct from (v_filter ->> 'boolean_value')::boolean then
        return false;
      end if;
    else
      return false;
    end if;
  end loop;

  return true;
end;
$$;

create or replace function catalog.search_products(
  p_tenant_id uuid,
  p_keyword text default null,
  p_business_statuses text[] default array['active']::text[],
  p_readiness_filter text default null,
  p_include_soft_deleted boolean default false,
  p_limit int default 50,
  p_offset int default 0,
  p_custom_field_filters jsonb default '[]'::jsonb
)
returns table (
  product_id uuid,
  name text,
  trade_name text,
  sku text,
  barcode text,
  primary_image_url text,
  business_status text,
  is_soft_deleted boolean,
  base_unit_name text,
  stock_qty numeric,
  list_price numeric,
  floor_price numeric,
  updated_at timestamptz,
  has_base_unit boolean,
  has_images boolean,
  has_stock boolean,
  has_base_price boolean,
  has_price_band boolean,
  has_required_custom_fields boolean,
  stock_mode text,
  base_price_mode text,
  custom_field_values jsonb,
  total_count bigint
)
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_keyword text;
  v_keyword_normalized text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  v_keyword := nullif(btrim(coalesce(p_keyword, '')), '');
  v_keyword_normalized := nullif(lower(v_keyword), '');

  return query
  with filtered as (
    select
      p.id,
      p.name,
      p.trade_name,
      p.sku,
      p.barcode,
      (
        select coalesce(i.file_url, i.storage_key)
        from catalog.product_images i
        where i.product_id = p.id
          and i.tenant_id = p_tenant_id
        order by i.is_primary desc, i.sort_order asc, i.created_at asc
        limit 1
      ) as primary_image_url,
      p.business_status::text as business_status,
      (p.deleted_at is not null) as is_soft_deleted,
      (
        select u.unit_name
        from catalog.product_units u
        where u.product_id = p.id
          and u.tenant_id = p_tenant_id
          and u.is_base_unit = true
        limit 1
      ) as base_unit_name,
      (
        select sp.initial_stock
        from catalog.product_stock_profiles sp
        where sp.product_id = p.id
          and sp.tenant_id = p_tenant_id
        limit 1
      ) as stock_qty,
      (
        select pb.list_price_amount
        from catalog.product_unit_price_bands pb
        join catalog.product_units bu
          on bu.id = pb.product_unit_id
         and bu.product_id = p.id
         and bu.is_base_unit = true
        where pb.product_id = p.id
          and pb.tenant_id = p_tenant_id
        limit 1
      ) as list_price,
      (
        select pb.floor_price_amount
        from catalog.product_unit_price_bands pb
        join catalog.product_units bu
          on bu.id = pb.product_unit_id
         and bu.product_id = p.id
         and bu.is_base_unit = true
        where pb.product_id = p.id
          and pb.tenant_id = p_tenant_id
        limit 1
      ) as floor_price,
      p.updated_at,
      f.has_base_unit,
      f.has_images,
      f.has_stock,
      f.has_base_price,
      f.has_price_band,
      f.has_required_custom_fields,
      f.stock_mode,
      f.base_price_mode
    from catalog.products p
    cross join lateral catalog._product_operational_facts(p_tenant_id, p.id) f
    where p.tenant_id = p_tenant_id
      and (p_include_soft_deleted or p.deleted_at is null)
      and p.business_status::text = any (p_business_statuses)
      and (
        v_keyword is null
        or p.name ilike '%' || v_keyword || '%'
        or coalesce(p.trade_name, '') ilike '%' || v_keyword || '%'
        or (v_keyword_normalized is not null and p.sku_normalized = v_keyword_normalized)
        or (v_keyword is not null and p.barcode_normalized = btrim(v_keyword))
        or catalog._product_matches_custom_field_keyword(p_tenant_id, p.id, v_keyword)
      )
      and catalog._product_matches_custom_field_filters(
        p_tenant_id,
        p.id,
        coalesce(p_custom_field_filters, '[]'::jsonb)
      )
  ),
  readiness_filtered as (
    select *
    from filtered f
    where p_readiness_filter is null
      or (
        p_readiness_filter = 'ready_to_sell'
        and catalog._product_readiness_is_ready(
          f.has_base_unit, f.has_images, f.has_stock, f.has_base_price,
          f.has_price_band, f.has_required_custom_fields, f.stock_mode, f.base_price_mode
        )
      )
      or (
        p_readiness_filter = 'incomplete'
        and not catalog._product_readiness_is_ready(
          f.has_base_unit, f.has_images, f.has_stock, f.has_base_price,
          f.has_price_band, f.has_required_custom_fields, f.stock_mode, f.base_price_mode
        )
      )
  ),
  counted as (
    select count(*)::bigint as total_count from readiness_filtered
  )
  select
    rf.id as product_id,
    rf.name,
    rf.trade_name,
    rf.sku,
    rf.barcode,
    rf.primary_image_url,
    rf.business_status,
    rf.is_soft_deleted,
    rf.base_unit_name,
    rf.stock_qty,
    rf.list_price,
    rf.floor_price,
    rf.updated_at,
    rf.has_base_unit,
    rf.has_images,
    rf.has_stock,
    rf.has_base_price,
    rf.has_price_band,
    rf.has_required_custom_fields,
    rf.stock_mode,
    rf.base_price_mode,
    catalog._product_custom_field_list_values_json(p_tenant_id, rf.id) as custom_field_values,
    c.total_count
  from readiness_filtered rf
  cross join counted c
  order by rf.updated_at desc
  limit greatest(p_limit, 0)
  offset greatest(p_offset, 0);
end;
$$;

create or replace function catalog.list_custom_field_filter_options(
  p_tenant_id uuid,
  p_max_options_per_field int default 50
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_max int := greatest(least(coalesce(p_max_options_per_field, 50), 200), 1);
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  if not iam.has_permission(p_tenant_id, 'catalog.product.view') then
    raise exception 'permission denied: catalog.product.view';
  end if;

  return coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'field_id', f.id,
          'group_id', g.id,
          'group_name', g.name,
          'field_name', f.name,
          'field_type', f.field_type,
          'options', case
            when f.field_type = 'singleSelect' then coalesce(
              (
                select jsonb_agg(
                  catalog._custom_field_option_to_json(o)
                  order by o.sort_order, o.label
                )
                from catalog.custom_field_options o
                where o.field_id = f.id
                  and o.is_active = true
                limit v_max
              ),
              '[]'::jsonb
            )
            else '[]'::jsonb
          end,
          'sort_order', g.sort_order * 1000 + f.sort_order
        )
        order by g.sort_order, f.sort_order, f.name
      )
      from catalog.custom_field_groups g
      join catalog.custom_fields f
        on f.group_id = g.id
       and f.tenant_id = p_tenant_id
      where g.tenant_id = p_tenant_id
        and g.status = 'active'
        and f.status = 'active'
        and f.is_filterable = true
        and f.field_type in ('singleSelect', 'boolean')
    ),
    '[]'::jsonb
  );
end;
$$;

create or replace function catalog.get_product_custom_field_snapshot(
  p_tenant_id uuid,
  p_product_ids uuid[],
  p_include_inactive_values boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = catalog, iam, pg_temp
as $$
declare
  v_products jsonb := '{}'::jsonb;
  v_product_id uuid;
  v_fields jsonb;
begin
  perform catalog._assert_product_permission(p_tenant_id, 'catalog.product.view_detail');

  if p_product_ids is null or cardinality(p_product_ids) = 0 then
    raise exception 'validation_exception: At least one product is required.';
  end if;

  if cardinality(p_product_ids) > 100 then
    raise exception 'validation_exception: At most 100 products can be read at once.';
  end if;

  foreach v_product_id in array p_product_ids
  loop
    if not exists (
      select 1
      from catalog.products p
      where p.tenant_id = p_tenant_id
        and p.id = v_product_id
        and p.deleted_at is null
    ) then
      raise exception 'product not found';
    end if;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'product_id', v_product_id,
          'field_id', f.id,
          'group_id', g.id,
          'group_name', g.name,
          'field_name', f.name,
          'field_type', f.field_type,
          'display_value', catalog._product_custom_field_display_value(
            f.field_type,
            v.value_text,
            v.value_number,
            v.value_date,
            v.value_boolean,
            o.label
          ),
          'text_value', v.value_text,
          'number_value', v.value_number,
          'date_value', v.value_date,
          'boolean_value', v.value_boolean,
          'option_id', v.value_option_id,
          'option_label', o.label,
          'is_active', (f.status = 'active' and g.status = 'active')
        )
        order by g.sort_order, f.sort_order, f.name
      ),
      '[]'::jsonb
    )
    into v_fields
    from catalog.custom_field_groups g
    join catalog.custom_fields f
      on f.group_id = g.id
     and f.tenant_id = p_tenant_id
    join catalog.product_custom_field_values v
      on v.custom_field_id = f.id
     and v.product_id = v_product_id
     and v.tenant_id = p_tenant_id
    left join catalog.custom_field_options o
      on o.id = v.value_option_id
    where g.tenant_id = p_tenant_id
      and (
        (g.status = 'active' and f.status = 'active')
        or coalesce(p_include_inactive_values, false)
      )
      and catalog._custom_field_value_is_valid(
        f.field_type,
        v.value_text,
        v.value_number,
        v.value_date,
        v.value_boolean,
        v.value_option_id
      );

    v_products := v_products || jsonb_build_object(v_product_id::text, v_fields);
  end loop;

  return jsonb_build_object('products', v_products);
end;
$$;

